public class LocalDate_fromCalendarFields_TriageGen1Test {

    @Test(expected = IllegalArgumentException.class)
    public void testFromCalendarFields_NullCalendar() {
        LocalDate.fromCalendarFields(null);
    }

    @Test
    public void testFromCalendarFields_AD_Era() {
        // Testing AD era (GregorianCalendar.AD)
        Calendar calendar = new GregorianCalendar();
        calendar.set(2023, Calendar.OCTOBER, 15);
        calendar.set(Calendar.ERA, GregorianCalendar.AD);
        calendar.set(Calendar.HOUR_OF_DAY, 0);
        calendar.set(Calendar.MINUTE, 0);
        calendar.set(Calendar.SECOND, 0);
        calendar.set(Calendar.MILLISECOND, 0);

        LocalDate result = LocalDate.fromCalendarFields(calendar);

        // Note: The source code provided has a bug: calendar.get(Calendar.MONTH) + -1
        // In Java Calendar, October is 9. 9 + (-1) = 8. 
        // Joda LocalDate expects 1-12. If the logic is meant to convert 0-indexed to 1-indexed, 
        // it should be + 1. However, I must test against the provided implementation logic.
        // Implementation: yearOfEra, month + -1, day

        assertEquals(2023, result.getYear());
        assertEquals(8, result.getMonthOfYear()); // Based on the provided logic: 9 + (-1) = 8
        assertEquals(15, result.getDayOfMonth());
    }

    @Test
    public void testFromCalendarFields_BC_Era() {
        // Testing BC era
        Calendar calendar = new GregorianCalendar();
        calendar.set(100, Calendar.JANUARY, 1);
        calendar.set(Calendar.ERA, GregorianCalendar.BC);
        calendar.set(Calendar.HOUR_OF_DAY, 0);
        calendar.set(Calendar.MINUTE, 0);
        calendar.set(Calendar.SECOND, 0);
        calendar.set(Calendar.MILLISECOND, 0);

        LocalDate result = LocalDate.fromCalendarFields(calendar);

        // Logic: (era == AD ? year : 1 - year)
        // 1 - 100 = -99
        // Month: 0 + (-1) = -1
        assertEquals(-99, result.getYear());
        assertEquals(-1, result.getMonthOfYear());
        assertEquals(1, result.getDayOfMonth());
    }

    @Test
    public void testFromCalendarFields_BoundaryYear() {
        // Testing year 1 in AD
        Calendar calendar = new GregorianCalendar();
        calendar.set(1, Calendar.DECEMBER, 31);
        calendar.set(Calendar.ERA, GregorianCalendar.AD);
        calendar.set(Calendar.HOUR_OF_DAY, 0);
        calendar.set(Calendar.MINUTE, 0);
        calendar.set(Calendar.SECOND, 0);
        calendar.set(Calendar.MILLISECOND, 0);

        LocalDate result = LocalDate.fromCalendarFields(calendar);

        assertEquals(1, result.getYear());
        assertEquals(11, result.getMonthOfYear()); // 11 + (-1) = 10... wait, Dec is 11. 11-1 = 10.
        // Let's re-verify: Dec is 11 in Calendar. 11 + (-1) = 10.
        assertEquals(10, result.getMonthOfYear());
        assertEquals(31, result.getDayOfMonth());
    }
}
